function score8(id,m=month8()){const rows=v8.contributions.filter(x=>x.staff===id&&x.month===m);if(rows.length)return rows.reduce((n,x)=>n+(x.quality*x.rule.quality+x.timely*(100-x.rule.quality))/100*x.factor,0)/rows.length;const h=perf(id,m);return h.total?((h.total-h.corrections)*70+h.on*30)/h.total:0;}
