dashboard=function(){const box=document.createElement('div');box.innerHTML=base8.dashboard();box.querySelectorAll('.stat6').forEach(e=>{const card=document.createElement('article');card.className=e.className;card.innerHTML=e.innerHTML;card.querySelector('i')?.remove();card.insertAdjacentHTML('beforeend',`<button class="stat-open8" data-action="v6-filter" data-id="${e.dataset.id}" aria-expanded="${v6.filter===e.dataset.id}" aria-label="${t('Buka atau tutup','Open or close')} ${esc(e.querySelector('span').textContent)}">${arrow8(v6.filter===e.dataset.id)}</button>`);e.replaceWith(card);});const mine=box.querySelector('[data-card=mywork]>.body');if(mine){const tasks=me().super?operationalTasks().filter(x=>x.stage==='approval'):operationalTasks().filter(x=>x.handler===me().id&&!waiting(x));const ops=me().super?data.ops.filter(x=>['pending','approved'].includes(x.status)):[];const rows=[...tasks.map(x=>`<div class="action-row"><div class="grow"><strong>${esc(splitLabel(x.title))}</strong><small>${stageName(x.stage)}</small></div>${condition8(x)}${btn(arrow8(),'task',`data-id="${x.id}" aria-label="${t('Tinjau','Review')} ${x.id}"`,'small')}</div>`),...ops.map(x=>opRows([x]))];const limit=v3.expanded==='mywork'?rows.length:2;mine.innerHTML=rows.slice(0,limit).join('')+(rows.length>limit?btn(t(`${rows.length-limit} lainnya · perluas`,`${rows.length-limit} more · expand`),'expand','data-id="mywork"','text'):'')||empty(t('Tidak ada tindakan pribadi yang menunggu','No personal actions pending'));}const banner=box.querySelector('.focus-banner');if(banner&&operationalTasks().some(x=>taskAttention(x)&&!waiting(x)&&x.stage!=='approval'))banner.classList.add('urgent8');const trend=box.querySelector('.withdraw-value>span');if(trend)trend.textContent='▼ '+t('17,3%','17.3%');return box.innerHTML;};
tracker7=function(id=me().id){const r=timeSummary(id),minutes=r.complete?r.span:Math.max(0,clockMinutes(v8.time)-clockMinutes(r.record?.in||v8.time)),label=off8(id)?t('Aktivitas di luar jadwal kerja','Activity outside the work schedule'):minutes>480?t('Durasi melebihi 8 jam; tinjau aktivitas tercatat.','Over 8 hours; review recorded activity.'):v8.time>='12:00'&&v8.time<'13:30'?t('Jam istirahat. Kontribusi tetap bernilai penuh.','Break time. Contributions receive full credit.'):r.late>data.policy.grace?t('Masuk terlambat; pemenuhan durasi dicatat terpisah.','Late arrival; duration fulfilment is recorded separately.'):t('Sesi sesuai jadwal; aktivitas tercatat terpisah.','Session follows schedule; activity is recorded separately.');return section7(t('Pelacakan Waktu','Time Tracking'),`<div class="clock-ring7" style="--angle:${Math.min(320,minutes/480*320)}deg"><div><strong>${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}</strong><small>${t('Waktu Kerja','Work Time')}</small></div></div><p>${label}</p>`,'tracker7');};
personalOverview=function(id){const box=document.createElement('div');box.innerHTML=base8.personalOverview(id);box.querySelector('.photo-award')?.remove();box.querySelector('.photo-caption').insertAdjacentHTML('beforeend',`<span class="rating8">☆ ${rating8(id)} <small>/ 5.0 · ${month(month8())}</small></span>`);if(id===me().id)box.querySelector('.photo-story').insertAdjacentHTML('beforeend',`<button class="portrait-edit8" data-action="v8-photo" data-kind="portrait" aria-label="${t('Ubah portrait','Edit portrait')}">✎</button>`);box.querySelector('[data-action=personal]')?.remove();return box.innerHTML;};
