function chartData8(id){const ids=id==='all'?people.map(p=>p.id):[id];return Array.from({length:7},(_,i)=>{const rows=ids.map(p=>week8(p)[i]);return {day:14+i,present:rows.every(x=>x.present!==null)?rows.reduce((s,x)=>s+x.present,0):null,active:rows.reduce((s,x)=>s+x.active,0)};});}
function smooth8(vals,max=40){let path='',prev=null;vals.forEach((v,i)=>{if(v==null){prev=null;return;}const x=38+i*82,y=180-v/max*145;if(!prev)path+=`M${x} ${y}`;else path+=` C${prev.x+41} ${prev.y},${x-41} ${y},${x} ${y}`;prev={x,y};});return path;}
function chartSVG8(rows,average=false){const max=Math.max(8,...rows.flatMap(r=>[r.present||0,r.active||0])),labels=t('Sen Sel Rab Kam Jum Sab Min','Mon Tue Wed Thu Fri Sat Sun').split(' ');return `<svg class="chart8" viewBox="0 0 570 225" role="img" aria-label="${t('Kehadiran dan aktivitas Senin sampai Minggu','Attendance and activity Monday through Sunday')}"><defs><linearGradient id="line8"><stop stop-color="#e79a36"/><stop offset="1" stop-color="#42b77d"/></linearGradient></defs>${[0,1,2,3,4].map(i=>`<path d="M38 ${180-i*36.25}H540" stroke="var(--line)" stroke-dasharray="4 5"/><text x="3" y="${184-i*36.25}">${n7(max*i/4)}h</text>`).join('')}<path d="${smooth8(rows.map(r=>r.present),max)}" stroke="${average?'url(#line8)':'#977bf5'}" stroke-width="3" fill="none"/>${!average?`<path d="${smooth8(rows.map(r=>r.active),max)}" stroke="#e9ad3c" stroke-width="3" fill="none"/>`:''}${rows.map((r,i)=>`<g><text x="${38+i*82}" y="212" text-anchor="middle">${labels[i]}</text><rect class="hit8" data-chart-index="${i}" x="${14+i*82}" y="25" width="49" height="165" fill="transparent" tabindex="0"><title>${r.day} Sep · ${t('Hadir','Present')} ${r.present==null?'—':n7(r.present)+'h'} · ${t('Aktivitas','Activity')} ${n7(r.active)}h</title></rect></g>`).join('')}</svg>`;}
curve7=function(id){const selected=me().super?v8.chartStaff:me().id,rows=chartData8(selected),total=rows.reduce((n,r)=>n+(r.present||0),0),active=rows.reduce((n,r)=>n+r.active,0),weekend=rows.slice(5).reduce((n,r)=>n+r.active,0);return section7(t('Kehadiran & Aktivitas Tercatat','Attendance & Recorded Activity'),`${me().super?`<select id="v8-chart-staff" aria-label="${t('Pilih staf','Choose staff')}"><option value="all">${t('Seluruh pengguna','All users')}</option>${people.map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${p.name}</option>`).join('')}</select>`:''}<div class="curve-metrics"><strong>${n7(total)}h<small>${t('Kehadiran terkonfirmasi','Confirmed attendance')}</small></strong><strong>${n7(active)}h<small>${t('Aktivitas tercatat','Recorded activity')}</small></strong></div>${chartSVG8(rows)}<div class="legend"><span style="color:#977bf5">● ${t('Hadir','Present')}</span><span style="color:#e9ad3c">● ${t('Aktivitas','Activity')}</span></div><p class="chart-note8" id="chart-note8">${weekend?t(`${n7(weekend)} jam aktivitas tercatat saat akhir pekan. Periksa konteks dan izin akses.`,`${n7(weekend)} hours of weekend activity recorded. Review context and access permission.`):t('Pekan 14–20 September. Tidak ada aktivitas akhir pekan. Rentang hadir belum lengkap ditampilkan sebagai celah, bukan nol.','September 14–20. No weekend activity. Incomplete attendance appears as a gap, not zero.')} ${t('Aktivitas di luar aplikasi dapat belum tercakup.','Work outside the app may not be covered.')}</p>`,'activity-chart8');};
function average8(){const ids=people.filter(p=>!p.super).map(p=>p.id),rows=Array.from({length:7},(_,i)=>{const complete=ids.map(id=>week8(id)[i]).filter(r=>r.present!==null);return {day:14+i,present:complete.length?complete.reduce((n,r)=>n+r.present,0)/complete.length:null,active:0};});const eligible=rows.slice(0,5).filter(r=>r.present!==null);const avg=eligible.reduce((n,r)=>n+r.present,0)/(eligible.length||1);return section7(t('Rata-rata Jam Hadir','Avg. Attendance Hours'),`<div class="spread"><strong class="payroll-number7">${n7(avg)}h</strong><small>14–20 Sep 2026</small></div>${chartSVG8(rows,true)}<p class="scope-note">${t('Rata-rata harian staf dengan catatan lengkap. Super Admin dikecualikan. Satuan jam hadir, bukan jam produktif.','Daily average among staff with complete records. Super Admins excluded. Attendance hours, not productive hours.')}</p>`);}
