kpi7=function(team=false){const ids=team?people.filter(p=>!p.super).map(p=>p.id):[me().super?v7.staff:me().id],months=kpiMonths8(),values=months.map(m=>{const eligible=ids.filter(id=>v8.contributions.some(x=>x.staff===id&&x.month===m)||perf(id,m).total);return eligible.length?eligible.reduce((s,id)=>s+score8(id,m),0)/eligible.length:null;}),current=values.at(-1),prior=values.at(-2),change=current!=null&&prior!=null?current-prior:null;return section7(team?t('Rata-rata KPI Tim','Average Team KPI'):t('Panel KPI','KPI Panel'),`<div class="spread"><small>${month(month8())}</small><select id="v8-kpi-period" aria-label="${t('Rentang KPI','KPI range')}">${[3,6,12].map(n=>`<option value="${n}" ${n===v8.periods?'selected':''}>${n} ${t('bulan','months')}</option>`).join('')}</select></div><div class="kpi-number">${n7(current??0)}<small>/100</small></div>${change==null?'':badge((change>=0?'▲ ':'▼ ')+n7(Math.abs(change))+t(' poin',' points'),change>=0?'green':'red')}<div class="kpi8-bars">${values.map((v,i)=>`<div class="kpi8-col"><b>${v==null?'—':n7(v)}</b><i style="height:${v==null?2:v}px"></i><small>${new Intl.DateTimeFormat(state.lang==='id'?'id-ID':'en-US',{month:'short'}).format(new Date(months[i]+'-01T12:00Z'))}</small></div>`).join('')}</div><p class="scope-note">${t('Skor memakai versi aturan pada setiap kontribusi. Riwayat kosong tidak dianggap nol.','Each contribution retains its rule version. Missing history is not treated as zero.')}</p>${btn(t('Bukti & aturan nilai','Evidence & scoring rules'),'v8-kpi','','text')}`,'kpi7');};
